    """Return a report for a savings goal."""
    goal = store.find_goal(name)
    if goal is None:
        raise ValueError(f"goal {name} not found")
    return {
        "name": goal.name,
        "target": goal.target,
        "saved": goal.saved,
        "progress": goal.saved / goal.target if goal.target > 0 else 0
    }"}

