    if any(g.goal_id == goal_id for g in goals):
        raise ValidationError(f"goal {goal_id} already exists")
    goal = SavingsGoal(goal_id, name, Decimal(target))
    goals.append(goal)
    return goal

def contribute(goal: SavingsGoal, amount: str) -> int:
    """Contribute to a savings goal.

    Returns the remaining amount needed.
    """
    contribution = Decimal(amount)
    if goal.saved + contribution >= goal.target:
        raise ValidationError(f"goal {goal.name} would be over target")
    goal.saved += contribution
    remaining = goal.target - goal.saved
    return int(remaining)

def goal_report(goals: list) -> list:
    """Return a report for all savings goals."""
    results = []
    for goal in goals:
        complete = goal.saved >= goal.target
        results.append({
            "name": goal.name,
            "target": goal.target,
            "saved": goal.saved,
            "complete": complete
        })
    return results

